import java.util.*;
import java.io.*;

public class Main {
    static int n_input, total_nodes, result_value;
    static int[] prefix_sum = new int[15];
    static List<Integer>[] sequences = new ArrayList[15];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n_input = Integer.parseInt(br.readLine());
        for (int i = 0; i < 15; i++) {
            sequences[i] = new ArrayList<>();
        }
        generate(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(sequences[i]);
        }
        total_nodes = 0;
        for (int i = 1; i <= 9; i++) {
            traverse(i);
        }
        System.out.println(result_value);
    }

    static void generate(int depth, int num) {
        if (depth == 7) return;
        total_nodes++;
        int val = ((total_nodes - num) % 998244353 + 998244353) % 998244353;
        sequences[depth].add(val);
        prefix_sum[depth] = (prefix_sum[depth] + val) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            generate(depth + 1, num * 10 + digit);
        }
    }

    static void traverse(int x) {
        if (x > n_input) return;
        if (x * 1000000 + 999999 <= n_input && x * 10 * 1000000 > n_input) {
            int currentCount = total_nodes;
            for (int i = 0, factor = 1; i <= 6; i++, factor *= 10) {
                int sizeVec = sequences[i].size();
                int diffVal = ((currentCount - x * factor) % 998244353 + 998244353) % 998244353;
                int target = 1000000000 - diffVal;
                int pos = lowerBound(sequences[i], target);
                result_value = (result_value + (long)diffVal * sizeVec + prefix_sum[i]) % 1000000007;
                int subtractVal = (998244353L * (sizeVec - pos)) % 1000000007;
                result_value = (result_value - subtractVal + 1000000007) % 1000000007;
                total_nodes += sizeVec;
            }
            return;
        }
        total_nodes++;
        result_value = (result_value + ((total_nodes - x) % 998244353 + 998244353) % 998244353) % 1000000007;
        for (int i = 0; i <= 9; i++) {
            traverse(x * 10 + i);
        }
    }

    static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
